// Lazo A · Review prep · arma la tarea de revisión para los 3 jefes sobre el
// borrador consolidado. Patrón SPEC-camino-iii-lazo-correccion: los jefes
// DIAGNOSTICAN (emiten correcciones accionables), el consolidador CORRIGE.
//
// 2026-08-04 (diff v2) · 3 cambios:
//  (a) FORMAT + TU EJE van ANTES de la evidencia · el recorte de cola sólo puede
//      comerse EVIDENCIA, nunca la instrucción de salida ni el eje del revisor.
//  (b) evidencia por LÍNEAS ETIQUETADAS con tope por campo · NO JSON.stringify().slice(),
//      que con 8 claves corta a mitad de token y entrega JSON roto.
//  (c) centinelas ('unknown') tratados como vacío · 2ª capa (la 1ª está en Fan-out prep).
const inp = $json;
const draft = inp.brand_book_draft || {};
const grounding = inp._grounding_refs || {};
const clientId = inp.client_id || draft.client_id;
const cycle = Number(inp.cycle) || 0;
// [GUARD P0 · CC#2 2026-07-02 re-apply post-revert] Skip degenerado · si EVIDENCIA
// o BORRADOR vacíos ({}/sin keys) → 0 items (los 3 revisores no corren · loop termina).
const _draftEmpty = !draft || typeof draft !== 'object' || Object.keys(draft).length === 0;
const _groundingEmpty = !grounding || typeof grounding !== 'object' || Object.keys(grounding).length === 0;
if (_draftEmpty || _groundingEmpty) {
  console.warn('[BBA][guard] skip review · brand_book_draft o _grounding_refs vacios · client=' + (clientId || '?') + ' cycle=' + cycle);
  return [];
}

const FORMAT =
  'Emití SOLO JSON: {"corrections":[{eje,campo,severidad,donde,problema,por_que,cambio_sugerido}]}.\n' +
  '- eje: "factual"|"voz"|"posicionamiento"|"cliente"\n' +
  '- campo: EXACTAMENTE uno de "positioning"|"icp_summary"|"voice_description"|' +
  '"forbidden_words"|"required_terminology"|"customer_angle"|"retention_notes"\n' +
  '- severidad: "rojo"|"ámbar" (rojo = choca con la evidencia / regla dura)\n' +
  '- Regla: NO emitas "rojo" sin un objeto-corrección accionable. Sin prosa.\n' +
  '- Si el borrador ya está bien en TU eje, devolvé {"corrections":[]}.';

// evidencia por líneas etiquetadas · nunca produce JSON a medias
const SENTINELAS = new Set(['unknown', 'no especificado', 'n/a', 'na', '-', '']);
const ev = (v) => { const s = String(v == null ? '' : v).trim().toLowerCase(); return SENTINELAS.has(s) ? '' : String(v).trim(); };
const ln = (label, v, max) => {
  const a = Array.isArray(v) ? v : (v ? [v] : []);
  const items = a.map((s) => typeof s === 'string' ? s : (s && (s.name || s.audience_segment)) || '')
                 .filter(Boolean).slice(0, 3).map((t) => String(t).replace(/\s+/g, ' ').trim().slice(0, max));
  return items.length ? '- ' + label + ': ' + items.join(' · ') + '\n' : '';
};
const icp = grounding.icp_signals || {};
const evidenciaTxt =
  (ev(grounding.client_name) ? 'Cliente: ' + ev(grounding.client_name) + '\n' : '') +
  (ev(grounding.industry) ? 'Industria: ' + ev(grounding.industry) + '\n' : '') +
  'Resumen: ' + String(grounding.discovery_summary || '').slice(0, 1200) + '\n' +
  ln('Competidores', (grounding.competitors || []).map((c) => c && c.name), 60) +
  ln('Segmentos ICP', icp.segments, 90) +
  ln('Dolores', icp.pain_points, 110) +
  ln('Objetivos', icp.goals, 110) +
  ln('Objeciones', icp.objections, 110) +
  ln('Canales preferidos', icp.preferred_channels, 60);

// HEAD · lo que NUNCA se puede recortar (instrucción + diagnóstico del juez)
const head =
  'Sos revisor de un borrador de BRAND BOOK. Diagnosticá (NO reescribas) contra la ' +
  'EVIDENCIA real del cliente. Tu rol corrige solo TU eje.\n\n' +
  FORMAT + '\n\n' +
  (Array.isArray(inp.low_fields) && inp.low_fields.length
    ? 'EL JUEZ REPROBÓ estos campos (groundedness < 0.85): ' +
      inp.low_fields.map((f) => f + ' (' + ((inp.scores || {})[f] == null ? '?' : (inp.scores || {})[f]) + ')').join(' · ') +
      '. Priorizá correcciones que SUBAN su groundedness contra la EVIDENCIA.\n\n'
    : '');
// TAIL · lo recortable, en orden de importancia creciente hacia el final
// PROYECCION AL LAZO (2026-08-09 CC#2) · el borrador REAL mide ~9.874 ch y la ventana del
// prompt es 3.000/2.500 ⇒ JSON.stringify(draft).slice() cortaba por el final y voice_description,
// customer_angle y retention_notes NO LLEGABAN NUNCA a sus revisores (hallazgo CC#1 · voz 0.50).
// El presupuesto esta al filo (Review ~7.923 vs 7.900) ⇒ NO se agranda la ventana: se PROYECTA.
// Cada revisor recibe SUS campos con holgura y el resto como contexto corto ⇒ los 5 entran
// ENTEROS para quien los diagnostica. Recorte POR CAMPO, nunca un slice global (no parte JSON).
// OJO: esto achica SOLO el texto del prompt. El canal de datos (brand_book_draft en el return)
// sigue llevando el borrador COMPLETO · si se proyectara ahi, se perderian campos en el cierre.
const _txt = (v, max) => {
  if (v === undefined || v === null) return undefined;
  if (Array.isArray(v)) { const o = []; let n = 0;
    for (const it of v) { const s = String(typeof it === "string" ? it : JSON.stringify(it));
      if (n + s.length > max) break; o.push(s.slice(0, max)); n += s.length; } return o; }
  const s = String(v); return s.length > max ? s.slice(0, max) : s;
};
const _proyectar = (d, mios, capMio, capOtro, ventana) => {
  const ORDEN = ["positioning","icp_summary","voice_description","forbidden_words","required_terminology","customer_angle","retention_notes"];
  let otro = capOtro;
  for (let intento = 0; intento < 6; intento++) {
    const out = {};
    for (const f of ORDEN) {
      if (d[f] === undefined || d[f] === null) continue;
      const v = _txt(d[f], mios.indexOf(f) !== -1 ? capMio : otro);
      if (v !== undefined && !(Array.isArray(v) ? v.length === 0 : !String(v).trim())) out[f] = v;
    }
    const s = JSON.stringify(out);
    if (s.length <= ventana || otro <= 40) return { obj: out, txt: s, _otro: otro };
    otro = Math.floor(otro / 2);
  }
  return { obj: {}, txt: "{}", _otro: otro };
};

// ventana 3.000 · el que diagnostica ve SUS campos con 1.000, el resto como contexto 250.
const MIOS = {
  "brand-strategist": ["positioning", "icp_summary"],
  "editor-en-jefe": ["voice_description", "forbidden_words", "required_terminology"],
  "jefe-client-success": ["customer_angle", "retention_notes"],
};
const _proy = {};
for (const k of Object.keys(MIOS)) _proy[k] = _proyectar(draft, MIOS[k], 1000, 250, 3000);
const tailFor = (k) =>
  'BORRADOR:\n' + _proy[k].txt + '\n\n' +
  'EVIDENCIA:\n' + evidenciaTxt.slice(0, 4000);

const cap = (t) => t.slice(0, 7900);
const reviewers = [
  { reviewer: 'brand-strategist', agent: 'brand-strategist',
    task: cap(head + 'TU EJE: posicionamiento + ICP · ¿el posicionamiento contradice la evidencia? ¿ICP refleja la data?\n\n' + tailFor('brand-strategist')) },
  // 2026-08-28 · el editor-en-jefe salió del lazo de CORRECCIÓN: su eje no gatea,
  // así que su dictamen nunca podía llegar al productor (4 de 4 descartadas en la
  // corrida 89028). Sigue siendo lente en la CONSTRUCCIÓN del manual · otro flujo.
  { reviewer: 'jefe-client-success', agent: 'jefe-client-success',
    task: cap(head + 'TU EJE: cliente · ¿el ICP/ángulo refleja la retención? ¿algo no aterriza en valor cliente?\n\n' + tailFor('jefe-client-success')) },
];

// FIX-FORWARD · UN solo item con las 3 tasks keyed por revisor (patrón [BB] Fan-out prep).
const tasks = {
  'brand-strategist': reviewers[0].task,
  'jefe-client-success': reviewers[1].task,
};
return [{ json: {
  tasks, brand_book_draft: draft, _grounding_refs: grounding, client_id: clientId, cycle,
  low_fields: Array.isArray(inp.low_fields) ? inp.low_fields : [],
  scores: inp.scores || {},
  _evidencia_chars: evidenciaTxt.length,
  _draft_chars: JSON.stringify(draft).length,
  _draft_proy_chars: { "brand-strategist": _proy["brand-strategist"].txt.length, "editor-en-jefe": _proy["editor-en-jefe"].txt.length, "jefe-client-success": _proy["jefe-client-success"].txt.length },
} }];

// Lazo A · Merge corrections · consolida las correcciones de los 3 jefes y
// decide si hay que seguir corrigiendo. NO vinculante (no es voto pass/reject ·
// spec Lazo A): es mejora iterativa hasta converger o agotar 3 ciclos (§150).
//
// Input: items de los 3 review-agents (cada uno con `response` = JSON corrections)
// Output: { brand_book_draft, _grounding_refs, client_id, cycle, corrections, keep_going }

// FIX 2026-06-30 (Fix B · recorte de volumen) · Lazo A a 1 ciclo. Es NO VINCULANTE
// (la fidelidad decide canon · no estos votos) · y era el multiplicador de costo
// (corría 3-4 ciclos × 3 revisores POR cada ciclo de fidelidad → ~60 invocaciones).
// Ahora · 1 pasada de diagnóstico + a lo sumo 1 re-síntesis · Re-síntesis → Exit
// (sin loop-back · ver build-correction-subworkflow.mjs).
const MAX_CYCLES = 3;
const items = $input.all();

// 2026-08-01 · CAUSA RAÍZ (commit 486ceaf "el Lazo A borraba el draft"): el borrador y la
// evidencia se toman del TRIGGER, no de items[0] — items[0] es la RESPUESTA HTTP de un
// revisor, y el nodo HTTP reemplaza el ítem ⇒ draft = {} ⇒ el juez puntuaba 0.
const trig = (() => { try { return $('Lazo A · trigger (Execute Workflow)').first().json || {}; } catch (e) { return {}; } })();
// 2026-08-28 (Sprint B · pieza d) · con la arista de vuelta puesta, el lazo da
// más de una vuelta. Si el nodo releyera el disparador: el contador quedaría
// congelado (bucle infinito) y el borrador volvería al original (la corrección
// de la vuelta anterior se perdería). Preferimos lo que dejó la vuelta previa;
// en la 1ª vuelta `$('…parse')` lanza porque el nodo aún no corrió → disparador.
const previo = (() => { try { return $('[BBA] Re-síntesis parse').first().json || {}; } catch (e) { return {}; } })();
const hayVueltaPrevia = !!(previo && previo.brand_book_draft && Object.keys(previo.brand_book_draft).length);
const src = hayVueltaPrevia ? previo : trig;
const draft = src.brand_book_draft || {};
const cycle = Number(src.cycle) || 0;
// La EVIDENCIA y los CAMPOS BAJOS salen SIEMPRE del disparador: son el insumo fijo
// del lazo, la re-síntesis no los reescribe, y `Re-síntesis parse` no propaga
// `low_fields` — tomarlos del previo ensancharía el alcance en la vuelta 2.
const grounding = trig._grounding_refs || {};
const clientId = trig.client_id || draft.client_id;
const lowFields = Array.isArray(trig.low_fields) ? trig.low_fields : [];

const VALID_EJE = new Set(['factual', 'voz', 'posicionamiento', 'cliente']);
const VALID_SEV = new Set(['rojo', 'ámbar', 'ambar']);

// 2026-08-28 (③) · los dictámenes ilegibles se CUENTAN. Antes se tragaban en
// silencio y «el revisor no encontró nada» se leía igual que «el revisor habló y
// no le entendimos».
const _rotos = [];
function extract(item, idx) {
  var text = '';
  try {
    const j = item.json || {};
    const body = j.body || j;
    text = typeof body.response === 'string' ? body.response : JSON.stringify(body);
    const m = text.match(/\{[\s\S]*\}/);
    if (!m) { _rotos.push({ i: idx, motivo: 'sin_json', muestra: String(text).slice(0, 140) }); return []; }
    const arr = (JSON.parse(m[0]).corrections) || [];
    return Array.isArray(arr) ? arr : [];
  } catch (e) {
    _rotos.push({ i: idx, motivo: String((e && e.message) || e).slice(0, 120), muestra: String(text).slice(0, 140) });
    console.warn('[BBA][roto] dictamen ilegible · revisor #' + idx + ' · ' + String((e && e.message) || e));
    return [];
  }
}

// consolida + sanea · descarta correcciones malformadas (no rompe el lazo ·
// hardening como en camino-iii voto-red-nunca-se-dropea, PR #233).
const corrections = [];
for (let _i = 0; _i < items.length; _i++) {
  const it = items[_i];
  for (const c of extract(it, _i)) {
    if (!c || typeof c !== 'object') continue;
    const eje = String(c.eje || '').toLowerCase();
    const sev = String(c.severidad || '').toLowerCase();
    if (!VALID_EJE.has(eje)) continue;
    corrections.push({
      eje,
      campo: String(c.campo || ''),   // se propaga · sin esto el productor no lo ve
      severidad: VALID_SEV.has(sev) ? sev.replace('ambar', 'ámbar') : 'ámbar',
      donde: String(c.donde || ''),
      problema: String(c.problema || ''),
      por_que: String(c.por_que || ''),
      cambio_sugerido: String(c.cambio_sugerido || ''),
    });
  }
}

// Re-sintetizar UNA vez si hay correcciones accionables · Re-síntesis → Exit
// (no hay loop-back · el cap de 1 ciclo lo da el wiring, no este contador).
// ADR-020 §7.3 · SOLO el ROJO dispara re-síntesis · el ámbar es advisory y NO itera.
// 2ª capa · relevancia-al-gate: solo amerita ciclo lo que puede mover la fidelidad
// (ejes factual/posicionamiento → positioning · icp_summary). Lo estilístico jamás cicla.
// 2026-08-04 (diff v2) · VOCABULARIO. Los revisores emiten el vocabulario que este mismo
// workflow les define en [BBA] Review prep ("factual"|"voz"|"posicionamiento"|"cliente").
// El filtro TRADUCE ese vocabulario a los campos que el juez realmente gatea. Antes exigía
// {factual,posicionamiento} y se comía en silencio TODOS los rojos de 'cliente' — que es
// justo donde vive el ICP (forense CC#1 · exec 76545 · el campo que hizo fallar el tiro).
const EJE_A_CAMPO = {
  posicionamiento: ['positioning'],
  cliente: ['icp_summary'],
  factual: ['positioning', 'icp_summary'],
  voz: [],
};
// 2ª capa (§7.3 relevancia-al-gate) · sólo amerita ciclo lo que puede mover EL campo QUE FALLÓ.
const objetivo = (Array.isArray(lowFields) && lowFields.length) ? lowFields : ['positioning', 'icp_summary'];
// 2026-08-28 · el filtro mira EL CAMPO. Medido en 88939 y 89028: 3 rojos sobre
// campos que el productor tiene PROHIBIDO escribir bloqueaban sólo por compartir
// eje con uno gateado. Al productor le llegaba «arreglá retention_notes» con la
// orden de reescribir únicamente positioning/icp_summary.
const CAMPOS_VALIDOS = ['positioning', 'icp_summary', 'voice_description',
  'forbidden_words', 'required_terminology', 'customer_angle', 'retention_notes'];
const _ruta = { declarado: 0, donde: 0, eje: 0 };
function campoDe(c) {
  const dec = String(c.campo || '').trim();
  if (CAMPOS_VALIDOS.indexOf(dec) !== -1) { _ruta.declarado++; return dec; }
  // red · el primer token de `donde` · convención observada 24/24, nunca pedida
  const tok = String(c.donde || '').trim().split(/[\s\u00b7,:(]/)[0];
  if (CAMPOS_VALIDOS.indexOf(tok) !== -1) { _ruta.donde++; return tok; }
  _ruta.eje++; return null;   // sin campo legible → se cae al eje (bloquea de más)
}
const apuntaAlObjetivo = (c) => {
  const campo = campoDe(c);
  return campo ? objetivo.indexOf(campo) !== -1
               : (EJE_A_CAMPO[c.eje] || []).some((f) => objetivo.indexOf(f) !== -1);
};
const bloqueantes = corrections.filter((c) =>
  c.severidad === 'rojo' &&
  apuntaAlObjetivo(c) &&
  c.cambio_sugerido.trim().length > 0);
// U1 (Consejero) · lo que el filtro DESCARTA tiene que VERSE. Sin esto, un eje nuevo o mal
// escrito se traga correcciones válidas en silencio — el defecto de 76545, otra vez.
const _desc = {};
for (const c of corrections) {
  if (bloqueantes.indexOf(c) !== -1) continue;
  const mapea = apuntaAlObjetivo(c);   // el descarte cuenta la MISMA historia que el filtro
  const motivo = !(c.eje in EJE_A_CAMPO) ? 'eje_desconocido'
               : !mapea ? 'eje_no_gateado'
               : c.severidad !== 'rojo' ? 'no_rojo'
               : 'sin_cambio_sugerido';
  const k = c.eje + '|' + c.severidad + '|' + motivo;
  if (!_desc[k]) _desc[k] = { eje: c.eje, severidad: c.severidad, motivo, conteo: 0 };
  _desc[k].conteo++;
}
const ejes_descartados = Object.keys(_desc).map((k) => _desc[k]);
// §7.3 · presupuesto top-N · el creador recibe foco, no un volcado de nitpicks.
const TOP_N = 5;
const bloqueantes_top = bloqueantes.slice(0, TOP_N);
// 2026-08-28 (Sprint B · pieza c) · el tope entra en la DECISIÓN. Antes esta
// línea sólo miraba los bloqueantes y `MAX_CYCLES` era un número muerto: con la
// arista de vuelta puesta, un rojo que el creador no logre resolver haría girar
// el lazo para siempre. Con el tope: hasta 3 correcciones y afuera.
const topeAgotado = cycle >= MAX_CYCLES;
const keepGoing = bloqueantes_top.length > 0 && !topeAgotado;

// CC#2 F3 · cuenta respuestas PARSEABLES con la clave `corrections` presente (aunque venga
// vacía) · NO por longitud (un revisor sin hallazgos es legítimo) ni por ausencia de `.error`
// (un 401 con neverError puede devolver {message}/{detail}/HTML y colarse como OK).
const parseable = (it) => { try {
  const b = (it.json && it.json.body) || it.json || {};
  const t = typeof b.response === 'string' ? b.response : JSON.stringify(b);
  const m = t.match(/\{[\s\S]*\}/);
  return !!m && Array.isArray(JSON.parse(m[0]).corrections);
} catch (e) { return false; } };
const reviewers_ok = items.filter(parseable).length;

return [{ json: {
  brand_book_draft: draft,
  _grounding_refs: grounding,
  client_id: clientId,
  cycle,
  corrections,
  corrections_bloqueantes: bloqueantes_top,
  keep_going: keepGoing,
  reviewers_ok,
  low_fields: lowFields,
  ejes_descartados,
  _lazo_a: { cycle, max_cycles: MAX_CYCLES, tope_agotado: topeAgotado,
             revisores_rotos: _rotos, ruta_campo: _ruta,
             motivo_parada: keepGoing ? null : (topeAgotado ? 'tope_agotado' : 'sin_bloqueantes'),
             corrections_count: corrections.length,
             bloqueantes_count: bloqueantes.length, keep_going: keepGoing, reviewers_ok,
             ejes_descartados },
} }];

// [BBA] Exit · borrador final · FAIL-CLOSED (2026-08-01).
// Los 3 pisos anteriores fallaban ABIERTOS:
//  (1) fc=0 reseteaba el contador del llamador ⇒ BUCLE INFINITO a ~5 llamadas por vuelta.
//  (2) un borrador vacío reemplazaba al bueno camino al juez.
//  (3) corrections se perdía justo en la rama donde SÍ se corrigió.
const j = $json;
const FC_AGOTADO = 99;   // ante la duda, AGOTADO · nunca reiniciar el contador del llamador
const src = (() => { try { return $('Lazo A · trigger (Execute Workflow)').first().json || {}; } catch (e) { return {}; } })();
let fc = FC_AGOTADO;
const n = Number(src._fidelity_cycle);
if (Number.isFinite(n) && n > 0) fc = n;
const out = j.brand_book_draft;
const draftOk = out && typeof out === 'object' && Object.keys(out).length > 0;

// 2026-08-08 (F) · el ciclo NO puede terminar en silencio. Precedente 76545: 5 correcciones
// emitidas, re-sintesis nunca corrida, resynth_ok:true firmado — descubierto A MANO 6 dias
// despues. Sin esto el padre imprime el MISMO mensaje si el ciclo trabajo y fallo que si no
// corrio nunca. INVARIANTE (CC#2): resynth_ok TRUE con el borrador SIN CAMBIAR es imposible.
const mc = (() => { try { return $('[BBA] Merge corrections').first().json || {}; } catch (e) { return {}; } })();
// 2026-08-28 (Sprint B · c.2) · los hechos de la re-síntesis salen de $json
// cuando el cierre llega por esa rama · y de la ÚLTIMA re-síntesis de la corrida
// cuando llega por la fusión (tope agotado o convergencia).
const _rp = (() => { try { return $('[BBA] Re-síntesis parse').first().json || {}; } catch (e) { return null; } })();
const rs = (j.resynth_ok !== undefined) ? j : (_rp || {});
// el tope frenando NO es el filtro comiéndose las correcciones · son cosas
// distintas y confundirlas manda a cazar un bug que no existe.
// (c.3) · dos formas de agotar el tope · la fusión lo detecta cuando el lazo
// vuelve a pasar por ella · la guarda corta ANTES, así que acá se deduce del ciclo.
const _max_c = Number(j._max_cycles) || 0;
const _tope_agotado = ((mc._lazo_a || {}).tope_agotado === true)
  || (_max_c > 0 && (Number(j.cycle) || 0) >= _max_c);
const _draft_sin_cambio = draftOk && JSON.stringify(out) === JSON.stringify(src.brand_book_draft || {});
const _corr_n = Array.isArray(mc.corrections) ? mc.corrections.length : 0;
const _lazo_esteril =
    (mc.reviewers_ok === 0)                                  ? 'revisores_sin_tool'
  // CC#2 cond.2 · 4a causa · EL bug de 76545: los revisores SI diagnosticaron y el filtro se
  // los comio entero. Ojo: tambien dispara si todo era ambar (descarte legitimo §7.3) ⇒ el
  // detalle de abajo dice cual de las dos cosas fue, sin obligar a mirar la traza.
  : (mc.keep_going === false && _corr_n > 0 && !_tope_agotado) ? 'filtro_descarto_todo'
  : (mc.keep_going === true && rs.resynth_ok === false)       ? 'resintesis_sin_tool'
  : (rs.resynth_ok === true && _draft_sin_cambio)             ? 'resintesis_sin_efecto'
  : null;   // null = la maquinaria funciono (aunque el manual no alcance)
const _esteril_detalle = _lazo_esteril === 'filtro_descarto_todo'
  ? { corrections: _corr_n, ejes_descartados: mc.ejes_descartados || [] }
  : (_lazo_esteril ? { corrections: _corr_n, reviewers_ok: mc.reviewers_ok } : null);
return [{ json: {
  brand_book_draft: draftOk ? out : src.brand_book_draft,   // piso · conserva el previo
  _grounding_refs: j._grounding_refs || src._grounding_refs,
  client_id: j.client_id || src.client_id,
  cycle: j.cycle,
  _fidelity_cycle: fc,
  corrections: j.corrections || [],
  reviewers_ok: (j.reviewers_ok !== undefined ? j.reviewers_ok : null),
  // 2026-08-04 (diff v2) · el default es NO. `undefined !== false` daba TRUE cuando la
  // re-síntesis NO corrió: un "listo falso" adentro del ciclo. NO toca FC_AGOTADO (otro bloque).
  resynth_ran: rs.resynth_ok !== undefined,
  resynth_ok: rs.resynth_ok === true,
  // por qué paró el lazo · 'tope_agotado' | 'sin_bloqueantes' | null
  motivo_parada: (mc._lazo_a || {}).motivo_parada || (_tope_agotado ? 'tope_agotado' : null),
  _draft_preserved: !draftOk,
  _lazo_esteril,
  _esteril_detalle,
  _draft_sin_cambio,
  _resynth_scope: j._resynth_scope || null,
  _scope_ausente: j._scope_ausente === true,
  _fuera_de_alcance: j._fuera_de_alcance || [],
  _lazo_a_done: true,
} }];

// [BBA] Re-síntesis prep · arma el task · SIN llamadas (el fetch salía del Code · CC#2/CC#3).
// Recorte por ÍTEMS COMPLETOS, no por caracteres: JSON.stringify().slice() corta a mitad de
// objeto y entrega JSON inválido al modelo (el patrón que ya dañó al juez).
const inp = $json;
const draft = inp.brand_book_draft || {};
const grounding = inp._grounding_refs || {};
const clientId = inp.client_id || draft.client_id;
const nextCycle = (Number(inp.cycle) || 0) + 1;
// top-N bloqueantes (§7.3) · si no vinieran, cae a corrections
const base = Array.isArray(inp.corrections_bloqueantes) && inp.corrections_bloqueantes.length
  ? inp.corrections_bloqueantes : (inp.corrections || []);
const capItems = (arr, max) => { const out = []; let len = 0;
  for (const it of arr) { const s = JSON.stringify(it); if (len + s.length > max) break; out.push(it); len += s.length; }
  return out; };
const correcciones = capItems(base, 2500);

// 2026-08-08 (E · anti whack-a-mole) · la re-sintesis pedia TODOS los campos aunque hubiera
// fallado UNO. positioning saco 8/8 sobre el umbral (0.92-0.97 · medicion 07-ago) y lo
// mandabamos a reescribir igual. ADR-020 §7: lo que YA pasa el gate NO se sigue corrigiendo.
// Ademas los bloqueantes que llegan aca solo pueden apuntar a positioning/icp_summary (mapa
// EJE_A_CAMPO), asi que reescribir voz/angulo/retencion desde ellos seria deriva pura.
const GATED = ['positioning', 'icp_summary'];
const lowF = (Array.isArray(inp.low_fields) && inp.low_fields.length) ? inp.low_fields : GATED;
const objetivo = GATED.filter((f) => lowF.indexOf(f) !== -1);
const preservar = GATED.filter((f) => objetivo.indexOf(f) === -1);

// 2026-08-04 (diff v2) · la INSTRUCCIÓN y las CORRECCIONES van ANTES de la evidencia:
// el recorte de cola sólo puede comerse EVIDENCIA, nunca el insumo de la re-síntesis.
// Y la evidencia va por LÍNEAS ETIQUETADAS (no JSON.stringify().slice(), que corta a
// mitad de token con 8 claves). Cuenta: 420 prosa + 2500 corr + 2500 draft + 2400 ev ≈ 7862.
const SENTINELAS = new Set(['unknown', 'no especificado', 'n/a', 'na', '-', '']);
const ev = (v) => { const s = String(v == null ? '' : v).trim().toLowerCase(); return SENTINELAS.has(s) ? '' : String(v).trim(); };
const ln = (label, v, max) => {
  const a = Array.isArray(v) ? v : (v ? [v] : []);
  const items = a.map((s) => typeof s === 'string' ? s : (s && (s.name || s.audience_segment)) || '')
                 .filter(Boolean).slice(0, 3).map((t) => String(t).replace(/\s+/g, ' ').trim().slice(0, max));
  return items.length ? '- ' + label + ': ' + items.join(' · ') + '\n' : '';
};
const _icp = grounding.icp_signals || {};
const evidenciaTxt =
  (ev(grounding.client_name) ? 'Cliente: ' + ev(grounding.client_name) + '\n' : '') +
  (ev(grounding.industry) ? 'Industria: ' + ev(grounding.industry) + '\n' : '') +
  'Resumen: ' + String(grounding.discovery_summary || '').slice(0, 1200) + '\n' +
  ln('Competidores', (grounding.competitors || []).map((c) => c && c.name), 60) +
  ln('Segmentos ICP', _icp.segments, 90) +
  ln('Dolores', _icp.pain_points, 110) +
  ln('Objetivos', _icp.goals, 110) +
  ln('Objeciones', _icp.objections, 110) +
  ln('Canales preferidos', _icp.preferred_channels, 60);

// PROYECCION AL LAZO (2026-08-09 CC#2) · el borrador REAL mide ~9.874 ch y la ventana del
// prompt es 3.000/2.500 ⇒ JSON.stringify(draft).slice() cortaba por el final y voice_description,
// customer_angle y retention_notes NO LLEGABAN NUNCA a sus revisores (hallazgo CC#1 · voz 0.50).
// El presupuesto esta al filo (Review ~7.923 vs 7.900) ⇒ NO se agranda la ventana: se PROYECTA.
// Cada revisor recibe SUS campos con holgura y el resto como contexto corto ⇒ los 5 entran
// ENTEROS para quien los diagnostica. Recorte POR CAMPO, nunca un slice global (no parte JSON).
// OJO: esto achica SOLO el texto del prompt. El canal de datos (brand_book_draft en el return)
// sigue llevando el borrador COMPLETO · si se proyectara ahi, se perderian campos en el cierre.
const _txt = (v, max) => {
  if (v === undefined || v === null) return undefined;
  if (Array.isArray(v)) { const o = []; let n = 0;
    for (const it of v) { const s = String(typeof it === "string" ? it : JSON.stringify(it));
      if (n + s.length > max) break; o.push(s.slice(0, max)); n += s.length; } return o; }
  const s = String(v); return s.length > max ? s.slice(0, max) : s;
};
const _proyectar = (d, mios, capMio, capOtro, ventana) => {
  const ORDEN = ["positioning","icp_summary","voice_description","forbidden_words","required_terminology","customer_angle","retention_notes"];
  let otro = capOtro;
  for (let intento = 0; intento < 6; intento++) {
    const out = {};
    for (const f of ORDEN) {
      if (d[f] === undefined || d[f] === null) continue;
      const v = _txt(d[f], mios.indexOf(f) !== -1 ? capMio : otro);
      if (v !== undefined && !(Array.isArray(v) ? v.length === 0 : !String(v).trim())) out[f] = v;
    }
    const s = JSON.stringify(out);
    if (s.length <= ventana || otro <= 40) return { obj: out, txt: s, _otro: otro };
    otro = Math.floor(otro / 2);
  }
  return { obj: {}, txt: "{}", _otro: otro };
};

// ventana 2.500 · el ALCANCE (lo que se reescribe) va con 950 · el resto es contexto 120,
// porque E.b ya garantiza que lo de fuera de alcance vuelve VERBATIM del borrador entero.
const _proyRes = _proyectar(draft, objetivo, 950, 120, 2500);

const task = (
  'Sos el consolidador del brand book (el MAKER · no un revisor). Mejorá el BORRADOR ' +
  'aplicando SOLO las CORRECCIONES de los jefes, grounded en la EVIDENCIA. NO inventes ' +
  'campos nuevos · mantené la estructura.\n' +
  'ALCANCE · reescribí ÚNICAMENTE: ' + objetivo.join(', ') + '.\n' +
  (preservar.length
    ? 'NO TOQUES ' + preservar.join(', ') + ' · ya pasó el gate de fidelidad. Devolvelo EXACTAMENTE igual.\n'
    : '') +
  'LLAMÁ EL TOOL `emit_brand_section` (pasá lens:"brand-strategist") con los campos del ' +
  'ALCANCE. NO narres · usá el tool.\n\n' +
  'CORRECCIONES:\n' + JSON.stringify(correcciones) + '\n\n' +
  'BORRADOR:\n' + _proyRes.txt + '\n\n' +
  'EVIDENCIA:\n' + evidenciaTxt.slice(0, 2400)
).slice(0, 7900);

return [{ json: { task, _evidencia_chars: evidenciaTxt.length, _draft_chars: JSON.stringify(draft).length, _draft_proy_chars: _proyRes.txt.length, brand_book_draft: draft, _grounding_refs: grounding, client_id: clientId,
  cycle: nextCycle, corrections: inp.corrections || [], _fidelity_cycle: inp._fidelity_cycle,
  // 2026-08-28 (Sprint B · c.3) · el tope VIAJA desde la fusión, donde está
  // definido. La guarda lo lee de acá · no lo vuelve a escribir.
  _max_cycles: Number((inp._lazo_a || {}).max_cycles) || 0,
  // CC#3 §3 · reviewers_ok se perdía justo en el camino CORREGIDO
  reviewers_ok: inp.reviewers_ok,
  _resynth_scope: objetivo } }];

// [BBA] Re-síntesis parse · mezcla la sección mejorada · marca resynth_ok · propaga corrections
// (la telemetría estaba invertida: llegaban [] justo cuando SÍ se corrigió).
const body = ($json && $json.body) || $json || {};
const src = (() => { try { return $('[BBA] Re-síntesis prep').first().json || {}; } catch (e) { return {}; } })();
const draft = src.brand_book_draft || {};
const clientId = src.client_id || draft.client_id;
let cand = body.brand_section || null;
if (!cand && typeof body.response === 'string') {
  const m = body.response.match(/\{[\s\S]*\}/);
  if (m) { try { const p = JSON.parse(m[0]); cand = p.brand_book_draft || p; } catch (e) {} }
}
// 2026-08-08 (E.b) · el merge era { ...draft, ...cand } ⇒ el modelo podia pisar CUALQUIER campo,
// incluido uno que YA pasaba el gate. Ahora solo entran los campos del ALCANCE · el resto queda
// VERBATIM. Lo que intento cambiar fuera de alcance NO se descarta en silencio: se cuenta.
// CC#2 cond.1 · FALLBACK CERRADO A VACIO: si el alcance no llega, es TUBERIA ROTA, no permiso
// para re-sintetizar a ciegas. No se acepta nada · el borrador vuelve verbatim · se marca.
const scope = (Array.isArray(src._resynth_scope) && src._resynth_scope.length) ? src._resynth_scope : null;
const _scope_ausente = scope === null;
const enScope = (!_scope_ausente && cand && typeof cand === 'object')
  ? Object.keys(cand).filter((k) => scope.indexOf(k) !== -1) : [];
// F2b · antes bastaba con que `cand` fuera un objeto CUALQUIERA (el fallback hace
// `p.brand_book_draft || p`): un {"error":"..."} daba resynth_ok=true y ensuciaba el borrador.
// Ahora exige >=1 campo EN ALCANCE.
const resynth_ok = enScope.length > 0;
const _fuera_de_alcance = [];
let improved = draft;
if (resynth_ok) {
  improved = Object.assign({}, draft);
  for (const k of Object.keys(cand)) {
    if (enScope.indexOf(k) !== -1) improved[k] = cand[k];
    else if (JSON.stringify(cand[k]) !== JSON.stringify(draft[k])) _fuera_de_alcance.push(k);
  }
  improved.client_id = clientId;
}
return [{ json: {
  brand_book_draft: improved,
  _grounding_refs: src._grounding_refs || {},
  client_id: clientId,
  cycle: src.cycle,
  _max_cycles: Number(src._max_cycles) || 0,   // (c.3) · sigue viajando hacia la guarda
  corrections: src.corrections || [],
  resynth_ok,
  _resynth_scope: scope,
  _scope_ausente,
  _fuera_de_alcance,
  // CC#3 §3 · misma inversión de telemetría que ya se cerró para corrections
  reviewers_ok: src.reviewers_ok,
} }];
